<?php
namespace App\Console\Commands;
use App\Models\CheckoutPayment;use App\Services\Accounting\AccountingExportService;use Illuminate\Console\Command;
class InvoiceExpiredCheckouts extends Command{
 protected$signature='checkout:invoice-expired {--limit=100}';protected$description='Sender ubetalte utsjekkinger til regnskap ved dagsavslutning';
 public function handle(AccountingExportService $accounting):int{$items=CheckoutPayment::whereIn('status',['pending','processing','failed'])->whereNull('invoiced_at')->where('expires_at','<=',now())->oldest('expires_at')->limit((int)$this->option('limit'))->get();foreach($items as$payment){$connection=$accounting->activeConnection($payment->organization_id);if(!$connection){$payment->update(['status'=>'failed','last_error'=>'Dagsavslutning: Ingen aktiv regnskapskobling.']);continue;}$invoice=$payment->invoiceExport;if($invoice->status==='exported'){$payment->update(['status'=>'expired','provider_status'=>'INVOICED','invoiced_at'=>now()]);continue;}$accounting->queue($invoice,$accounting->providerName($connection));if($accounting->processQueued($invoice))$payment->update(['status'=>'expired','provider_status'=>'INVOICED','invoiced_at'=>now(),'last_error'=>null]);else$payment->update(['status'=>'failed','last_error'=>$invoice->fresh()->last_error]);}$this->info($items->count().' ubetalte betalinger behandlet i dagsavslutningen.');return self::SUCCESS;}
}
